import sys

def Reduced_String(k, s):
    if k == 1:
        return ""

    stack = []  # Each element is [char, count]

    for char in s:
        if stack and stack[-1][0] == char:
            stack[-1][1] += 1
            if stack[-1][1] == k:
                stack.pop()
        else:
            stack.append([char, 1])

    result = []
    for char, count in stack:
        result.append(char * count)

    return "".join(result)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    k = int(input_data[0])
    s = input_data[1] if len(input_data) > 1 else ""

    result = Reduced_String(k, s)
    print(result)

if __name__ == "__main__":
    main()
